cd claude-code-game-master/build/_qa-r3; cat > samp.js <<'EOF'
const SEL='.fx-pop,.toast,.sheet,.preview,.boot,.tok__under,[class*=pop],[class*=toast]';
const seenT={}; 
const sample=()=>{ const st=R.stage(); const q=st.getBoundingClientRect(); for(const el of st.querySelectorAll(SEL)){ if(!R.rotOf) break; const t=el.textContent.replace(/\s+/g,' ').trim(); if(!t||t.length>60) continue; const b=el.getBoundingClientRect(); if(!b.width) continue; const cs=getComputedStyle(el); if(cs.display==='none'||parseFloat(cs.opacity)<0.2) continue; const a=R.rotOf(el); const half=((b.top+b.bottom)/2-q.top)>q.height/2?'low':'up'; const k=t+' | '+a+'°/'+half+' | '+el.className.toString().slice(0,40); seenT[k]=(seenT[k]||0)+1; } };
const iv=setInterval(sample,60);
const done=()=>{clearInterval(iv); const by={}; for(const k of Object.keys​(seenT)){ const [t,a]=k.split(' | '); (by[t]=by[t]||new Set()).add(a.split('/')[0]); } const out={}; for(const t in by) out[t]=[...by[t]].join(','); return out; };
EOF
cat > run.sh <<'EOF'
#!/bin/bash
# run.sh HASH ROT : stdin = js body (has R, W, samp helpers); prints result
D=claude-code-game-master/build/_qa-r3
R=$([ "$2" = 1 ] && echo true || echo false)
timeout 60 python3 $D/s.py "{\"op\":\"load\",\"hash\":\"$1\",\"rot\":$R,\"settle\":1.5}" >/dev/null
BODY=$(cat)
{ cat $D/samp.js; echo "const log=[]; try { $BODY } catch(e){ log.push('EXC '+e) } await R.sleep(500); return {log, seen: done()};"; } | timeout 300 python3 $D/s.py js | python3 -c 'import json,sys; o=json.load(sys.stdin); r=o.get("r") or {}
print(" log:", json.dumps(r.get("log"),ensure_ascii=False) if isinstance(r,dict) else r, o.get("err"), o.get("exc") or "")
for k,v in (r.get("seen") or {}).items(): print("  ", k, "->", v)'
EOF
